-- Throwaway databases with different locale setups
DROP DATABASE IF EXISTS t_c;      CREATE DATABASE t_c      TEMPLATE template0 ENCODING 'UTF8' LOCALE 'C';
DROP DATABASE IF EXISTS t_posix;  CREATE DATABASE t_posix  TEMPLATE template0 ENCODING 'UTF8' LOCALE 'POSIX';
DROP DATABASE IF EXISTS t_builtin;CREATE DATABASE t_builtin TEMPLATE template0 ENCODING 'UTF8' LOCALE_PROVIDER builtin BUILTIN_LOCALE 'C.UTF-8';
DROP DATABASE IF EXISTS t_builtin_c;CREATE DATABASE t_builtin_c TEMPLATE template0 ENCODING 'UTF8' LOCALE_PROVIDER builtin BUILTIN_LOCALE 'C';
DROP DATABASE IF EXISTS t_icu;    CREATE DATABASE t_icu    TEMPLATE template0 ENCODING 'UTF8' LOCALE_PROVIDER icu ICU_LOCALE 'und' LOCALE 'C';
DROP DATABASE IF EXISTS t_icu_en; CREATE DATABASE t_icu_en TEMPLATE template0 ENCODING 'UTF8' LOCALE_PROVIDER icu ICU_LOCALE 'en-US' LC_COLLATE 'en_US.UTF-8' LC_CTYPE 'en_US.UTF-8';
DROP DATABASE IF EXISTS t_en;     CREATE DATABASE t_en     TEMPLATE template0 ENCODING 'UTF8' LOCALE 'en_US.UTF-8';
DROP DATABASE IF EXISTS t_cutf8;  CREATE DATABASE t_cutf8  TEMPLATE template0 ENCODING 'UTF8' LOCALE 'C.UTF-8';
DROP DATABASE IF EXISTS t_ar;     CREATE DATABASE t_ar     TEMPLATE template0 ENCODING 'UTF8' LOCALE 'ar_EG.UTF-8';
-- builtin provider but libc LC_CTYPE set to C.UTF-8 (collation stays code-point C)
DROP DATABASE IF EXISTS t_builtin_ctype;CREATE DATABASE t_builtin_ctype TEMPLATE template0 ENCODING 'UTF8' LOCALE_PROVIDER builtin BUILTIN_LOCALE 'C.UTF-8' LC_COLLATE 'C' LC_CTYPE 'C.UTF-8';
-- libc: collate C (fast, byte order) + ctype C.UTF-8
DROP DATABASE IF EXISTS t_libc_mixed;CREATE DATABASE t_libc_mixed TEMPLATE template0 ENCODING 'UTF8' LC_COLLATE 'C' LC_CTYPE 'C.UTF-8';
